1	const PROCESSING_FEE = 5;
2	
3	export type Item = {
4	  type: string;
5	  material?: string;
6	  enchantment?: number;
7	  cursed?: boolean;
8	};
9	
10	export type Step = {
11	  op: string;
12	  items: Item[];
13	};
14	
15	export type Customer = {
16	  yearsWithMHPCO: number;
17	};
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type StepResult = {
25	  premium: number;
26	};
27	
28	export type ScenarioResults = {
29	  results: StepResult[];
30	};
31	
32	const BASE_PREMIUMS: Record<string, number> = {
33	  sword: 100,
34	  amulet: 60,
35	  staff: 80,
36	  potion: 40,
37	  rune: 25,
38	  moonstone: 25,
39	};
40	
41	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
42	
43	// Percentages are applied as `amount * percent / 100` rather than
44	// `amount * 1.percent`, so that integer amounts stay exact: 100 * 1.1 is
45	// 110.00000000000001 in binary floating point, while 100 * 10 / 100 is 10.
46	const percentOf = (amount: number, percent: number): number =>
47	  (amount * percent) / 100;
48	
49	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type];
50	
51	const withFirstInsuranceSurcharge = (base: number): number =>
52	  base + percentOf(base, FIRST_INSURANCE_SURCHARGE_PERCENT);
53	
54	const BLOCK_SIZE = 3;
55	const BLOCK_BASE_PREMIUM = 60;
56	
57	// Items of the same type are priced together, so a policy is partitioned into
58	// same-type groups before any group pricing rule is applied.
59	const groupByType = (items: Item[]): Item[][] => {
60	  const groupsByType = new Map<string, Item[]>();
61	  for (const item of items) {
62	    const alike = groupsByType.get(item.type) ?? [];
63	    alike.push(item);
64	    groupsByType.set(item.type, alike);
65	  }
66	  return [...groupsByType.values()];
67	};
68	
69	const sumOf = <T>(values: T[], amount: (value: T) => number): number =>
70	  values.reduce((total, value) => total + amount(value), 0);
71	
72	// A building block of exactly 3 alike components is offered at a flat rate.
73	const groupBasePremium = (alike: Item[]): number =>
74	  alike.length === BLOCK_SIZE
75	    ? BLOCK_BASE_PREMIUM
76	    : sumOf(alike, basePremium);
77	
78	const itemsBasePremium = (items: Item[]): number =>
79	  sumOf(groupByType(items), groupBasePremium);
80	
81	const CURSE_SURCHARGE_PERCENT = 50;
82	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
83	const HIGH_ENCHANTMENT_LEVEL = 5;
84	
85	const isCursed = (item: Item): boolean => item.cursed === true;
86	
87	const isHighlyEnchanted = (item: Item): boolean =>
88	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
89	
90	// Each rule charges its percent of the affected item's own base premium.
91	type ItemSurchargeRule = {
92	  applies: (item: Item) => boolean;
93	  percent: number;
94	};
95	
96	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
97	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
98	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
99	];
100	
101	// Item-specific surcharges apply to the base premium of the affected item.
102	// Several can apply to the same item, so every matching rule is summed.
103	const itemSurcharges = (item: Item): number => {
104	  const base = basePremium(item);
105	  return sumOf(
106	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)),
107	    (rule) => percentOf(base, rule.percent),
108	  );
109	};
110	
111	const LOYALTY_DISCOUNT_PERCENT = 20;
112	const LOYALTY_YEARS = 2;
113	
114	const isLongStanding = (customer: Customer): boolean =>
115	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
116	
117	// Policy-wide modifiers adjust the policy base; item-specific surcharges are
118	// computed against each item's own unmodified base. Both are ADDITIVE against
119	// the base rather than compounding, so they are summed side by side and never
120	// nested inside one another. Discounts are negative percentages.
121	const withPolicyModifiers = (policyBase: number, customer: Customer): number => {
122	  const loyalty = isLongStanding(customer)
123	    ? -percentOf(policyBase, LOYALTY_DISCOUNT_PERCENT)
124	    : 0;
125	  return withFirstInsuranceSurcharge(policyBase) + loyalty;
126	};
127	
128	const policyPremium = (items: Item[], customer: Customer): number =>
129	  withPolicyModifiers(itemsBasePremium(items), customer) +
130	  sumOf(items, itemSurcharges);
131	
132	// Amounts are rounded in the MHPCO's favor: premiums round up.
133	const roundPremium = (amount: number): number => Math.ceil(amount);
134	
135	const quote = (step: Step, customer: Customer): StepResult => ({
136	  premium: roundPremium(PROCESSING_FEE + policyPremium(step.items, customer)),
137	});
138	
139	export const runScenario = (scenario: Scenario): ScenarioResults => ({
140	  results: scenario.steps.map((step) => quote(step, scenario.customer)),
141	});
